    }

    public static long longOverflowingMul(long a, long b) {
	try {
	    return Math.multiplyExact(a, b);
	} catch (ArithmeticException e) {
	    throw Utility.makeFortressException("fortress.CompilerBuiltin$IntegerOverflow");
	}
    }

